import React from "react";
import {Composition} from "remotion";
import {Scene} from "./Scene";

const defaultProps = {} as const;

export const BieComposition: React.FC = () => {
  return (
    <Composition
      id={"BieBuildFixture"}
      component={Scene}
      width={640}
      height={360}
      fps={24}
      durationInFrames={48}
      defaultProps={{...defaultProps}}
    />
  );
};

import React from "react";
import {BieComposition} from "./Composition";

export const RemotionRoot: React.FC = () => {
  return <BieComposition />;
};

import React from "react";
import {AbsoluteFill, Sequence} from "remotion";
import {TechnicalFixture} from "./TechnicalFixture";

export const Scene: React.FC = () => {
  return (
    <AbsoluteFill name="Scene" style={{backgroundColor: "white"}}>
      <Sequence name={"technical"} from={0} durationInFrames={48}>
        <TechnicalFixture {...({})} />
      </Sequence>
    </AbsoluteFill>
  );
};

import React from "react";
import {useCurrentFrame, interpolate} from "remotion";
import {BieReveal} from "./primitives";

export const TechnicalFixture: React.FC = () => {
  const frame = useCurrentFrame();
  const x = interpolate(frame, [0, 47], [50, 490], {extrapolateRight: "clamp"});
  return <BieReveal durationInFrames={12}>
    <div style={{fontFamily: "sans-serif", padding: 24, color: "black"}}>
      <h2>BIE compiler execution fixture</h2>
      <p>Technical test only — not an accepted learning video.</p>
      <div style={{position: "absolute", left: x, top: 195, width: 64, height: 64,
                   border: "4px solid black", transform: `rotate(${frame * 3}deg)`}} />
      <p style={{position: "absolute", bottom: 20}}>Frame {frame} / 47</p>
    </div>
  </BieReveal>;
};

import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export const BieAbsoluteScene: React.FC<React.PropsWithChildren<{
  backgroundColor?: string;
}>> = ({backgroundColor = "white", children}) => {
  return (
    <AbsoluteFill style={{backgroundColor}}>
      {children}
    </AbsoluteFill>
  );
};

export const BieReveal: React.FC<React.PropsWithChildren<{
  fromFrame?: number;
  durationInFrames?: number;
}>> = ({fromFrame = 0, durationInFrames = 15, children}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const safeDuration = Math.max(1, durationInFrames);

  return (
    <div
      style={{
        opacity: interpolate(
          frame,
          [fromFrame, fromFrame + safeDuration],
          [0, 1],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.16, 1, 0.3, 1),
          },
        ),
      }}
      data-bie-fps={fps}
    >
      {children}
    </div>
  );
};
